PAGES=[]
for slug,title,group,purpose,yes,no,tokens,scripts,live,init,api,a11y,limits in SPECS:
    PAGES.append(dict(
      slug=slug,title=title,group=group,purpose=purpose,status='экспериментальный' if slug not in ('breadcrumbs','details-sidebar') else 'стабильный',
      files=['css/components.css']+['js/'+s for s in scripts],scripts=scripts,
      live=live,live_script=('document.addEventListener("DOMContentLoaded", function(){'+init+'});' if init else ''),
      when_yes=[yes],when_no=[no],anatomy_html='<div inert aria-hidden="true">'+live.replace('advanced-', 'anatomy-')+'</div>',
      anatomy=[('Контекст',purpose),('Данные и действие','Живой пример показывает контракт подключения; демонстрационные данные не являются производственным срезом.')],
      variants=[(api[0][0],'Основной контракт API/markup.','При задаче, описанной выше.')],
      sizes='Компонент следует ширине контейнера и системным токенам. '+a11y,
      states='<p>'+limits+'</p>',content_ok=[yes,'Показывайте полные названия, единицы и источник данных.'],content_bad=[no,'Не выдавайте отсутствие наблюдений за ноль и не используйте цвет как единственное объяснение.'],
      a11y=[a11y,'Dark/light берутся из ближайшего dk-root; reduced motion не требует анимации. Проверки DOM/клавиатуры не заменяют живой скринридер или физический телефон.'],
      tokens=tokens,code=live+('\n<script>\n'+init+'\n</script>' if init else ''),api=api,
      related=[('component-table.html','Таблица','точные числа'),('README.md','Подключение','dk-theme первым, dk-util до компонента')]))
